def choose_move(observation):
    # Defensive extraction of observation fields
    game_type = observation.get('game_type', '')
    position = observation.get('position', [0, 0])
    x, y = position
    dx, dy = 0, 0

    # Helper function to find closest point and direction
    def get_direction(targets):
        min_dist = float('inf')
        target = None
        for t in targets:
            if not t:
                continue
            t_x, t_y = t[:2]
            dist = abs(t_x - x) + abs(t_y - y)
            if dist < min_dist:
                min_dist = dist
                target = (t_x, t_y)
        if target:
            d_x = 1 if target[0] > x else -1 if target[0] < x else 0
            d_y = 1 if target[1] > y else -1 if target[1] < y else 0
            return d_x, d_y
        return 0, 0

    if game_type == 'resource_collection':
        resources = observation.get('resources', [])
        dx, dy = get_direction(resources)

    elif game_type == 'pursuit_evasion':
        adversaries = observation.get('adversaries', [])
        dx, dy = get_direction(adversaries)

    elif game_type == 'territory_control':
        enemy_positions = observation.get('enemy_positions', [])
        min_dist = float('inf')
        threat = None
        for enemy in enemy_positions:
            if not enemy:
                continue
            ex, ey = enemy[:2]
            dist = abs(ex - x) + abs(ey - y)
            if dist < min_dist:
                min_dist = dist
                threat = (ex, ey)
        if threat:
            dx = -1 if threat[0] > x else 1 if threat[0] < x else 0
            dy = -1 if threat[1] > y else 1 if threat[1] < y else 0
        else:
            dx, dy = 0, 0

    # Move away from threats or resources if nearby
    # For territory_control, if no immediate threat, do a default move
    # Let's implement a simple tactic: if resource or adversary close, move towards; else stay still
    # Already handled above; now, fallback to moving randomly or staying put
    if dx == 0 and dy == 0:
        # Simple fallback: move any direction to explore
        dx, dy = 1, 0

    # Bound dx, dy to -1, 0, or 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]
